def _fit_nls(X, y, predict_fn, unpack_fn, pack_fn, init_params,
             n_restarts=14, use_log=False, f_scale=0.1):
    """Nonlinear least squares with multiple restarts."""
    y = np.asarray(y, dtype=float)
    u0_init = np.asarray(pack_fn(init_params), dtype=float)
    rng = np.random.default_rng(42)

    candidates = [u0_init]
    for scale in np.linspace(0.05, 0.6, max(n_restarts - 1, 1)):
        candidates.append(u0_init + rng.normal(scale=scale, size=u0_init.shape))

    best_u, best_score = u0_init, float("inf")
    for u0 in candidates:
        def _resid(u, _X=X, _y=y, _pf=predict_fn, _uf=unpack_fn, _ul=use_log):
            try:
                params = _uf(u)
                pred = _pf(_X, params)
                if _ul:
                    pred_s = np.clip(pred, EPS, None)
                    y_s = np.clip(_y, EPS, None)
                    r = np.log(pred_s) - np.log(y_s)
                else:
                    r = pred - _y
                return np.nan_to_num(r, nan=1e3, posinf=1e3, neginf=-1e3)
            except Exception:
                return np.full(len(_y), 1e3)
        try:
            result = least_squares(_resid, u0, method="trf",
                                   loss="soft_l1", f_scale=f_scale, max_nfev=8000)
            u_opt = result.x
        except Exception:
            u_opt = np.asarray(u0, dtype=float)
        try:
            params = unpack_fn(u_opt)
            pred = predict_fn(X, params)
            if use_log:
                score = float(np.mean((np.log(np.clip(pred, EPS, None))
                                       - np.log(np.clip(y, EPS, None))) ** 2))
            else:
                score = float(np.mean((pred - y) ** 2))
        except Exception:
            score = float("inf")
        if np.isfinite(score) and score < best_score:
            best_score, best_u = score, u_opt
    return unpack_fn(best_u)


# ---- VOCAB: L = E + A*N^(-a) + B*V^(-b) + C*D^(-g) ----

def _vocab_predict(X, params):
    n = np.clip(np.asarray(X[:, 0], dtype=float), 1.0, None)
    v = np.clip(np.asarray(X[:, 1], dtype=float), 1.0, None)
    d = np.clip(np.asarray(X[:, 2], dtype=float), 1.0, None)
    E, A, a, B, b, C, g = params
    return E + A * np.power(n, -a) + B * np.power(v, -b) + C * np.power(d, -g)


def _vocab_fit(X, y):
    y = np.asarray(y, dtype=float)
    def unpack(u):
        return np.array([u[0], np.exp(u[1]), np.exp(u[2]), np.exp(u[3]),
                         np.exp(u[4]), np.exp(u[5]), np.exp(u[6])])
    def pack(p):
        return np.array([p[0],
                         np.log(max(abs(p[1]), 1e-12)), np.log(max(p[2], 1e-12)),
                         np.log(max(abs(p[3]), 1e-12)), np.log(max(p[4], 1e-12)),
                         np.log(max(abs(p[5]), 1e-12)), np.log(max(p[6], 1e-12))])
    y_med, y_std = float(np.median(y)), max(float(np.std(y)), 0.1)
    init = np.array([y_med - y_std, y_std, 0.08, y_std, 0.25, y_std, 0.25])
    return _fit_nls(X, y, _vocab_predict, unpack, pack, init,
                    n_restarts=16, use_log=False, f_scale=0.05)


# ---- LRBSZ: polynomial + physical ensemble ----

def _make_lrbsz_features(X):
    lr = np.clip(np.asarray(X[:, 0], dtype=float), 1e-12, None)
    bsz = np.clip(np.asarray(X[:, 1], dtype=float), 1.0, None)
    d = np.clip(np.asarray(X[:, 2], dtype=float), 1.0, None)
    n = np.clip(np.asarray(X[:, 3], dtype=float), 1.0, None)
    ln_lr, ln_bsz = np.log(lr), np.log(bsz)
    ln_d, ln_n = np.log(d), np.log(n)
    return np.column_stack([
        np.ones(len(X)), ln_n, ln_d, ln_lr, ln_bsz,
        ln_lr ** 2, ln_bsz ** 2,
        ln_lr * ln_n, ln_lr * ln_d,
        ln_bsz * ln_d, ln_n * ln_d,
    ])


def _lrbsz_predict_linpoly(X, c):
    return _make_lrbsz_features(X) @ c


def _lrbsz_predict_logpoly(X, c):
    return np.exp(_make_lrbsz_features(X) @ c)


def _lrbsz_fit_poly(X, y):
    y = np.asarray(y, dtype=float)
    F = _make_lrbsz_features(X)
    reg = 0.01
    FtF = F.T @ F + reg * np.eye(F.shape[1])
    # Linear poly
    c_lin = np.linalg.solve(FtF, F.T @ y)
    pred_lin = F @ c_lin
    mse_lin = float(np.mean((pred_lin - y) ** 2))
    # Log poly
    log_y = np.log(np.clip(y, EPS, None))
    c_log = np.linalg.solve(FtF, F.T @ log_y)
    pred_log = np.exp(F @ c_log)
    mse_log = float(np.mean((pred_log - y) ** 2))
    if mse_lin <= mse_log:
        return ("linpoly", c_lin), mse_lin
    return ("logpoly", c_log), mse_log


def _lrbsz_predict_phys(X, params):
    lr = np.clip(np.asarray(X[:, 0], dtype=float), 1e-12, None)
    bsz = np.clip(np.asarray(X[:, 1], dtype=float), 1.0, None)
    d = np.clip(np.asarray(X[:, 2], dtype=float), 1.0, None)
    n = np.clip(np.asarray(X[:, 3], dtype=float), 1.0, None)
    E, A, al, B, be, K, la, ln_c, ld_c, M, bd, bb = params
    log_lr_opt = la + ln_c * np.log(n) + ld_c * np.log(d)
    log_bsz_opt = bb + bd * np.log(d)
    base = E + A * np.power(n, -al) + B * np.power(d, -be)
    return base + K * (np.log(lr) - log_lr_opt) ** 2 + M * (np.log(bsz) - log_bsz_opt) ** 2


def _lrbsz_fit_phys(X, y):
    y = np.asarray(y, dtype=float)
    lr = np.clip(np.asarray(X[:, 0], dtype=float), 1e-12, None)
    bsz = np.clip(np.asarray(X[:, 1], dtype=float), 1.0, None)
    # Stage 1: Chinchilla base
    def base_pred(X, p):
        nn = np.clip(np.asarray(X[:, 3], dtype=float), 1.0, None)
        dd = np.clip(np.asarray(X[:, 2], dtype=float), 1.0, None)
        return p[0] + p[1] * np.power(nn, -p[2]) + p[3] * np.power(dd, -p[4])
    def base_unpack(u):
        return np.array([u[0], np.exp(u[1]), np.exp(u[2]), np.exp(u[3]), np.exp(u[4])])
    def base_pack(p):
        return np.array([p[0], np.log(max(p[1], 1e-12)), np.log(max(p[2], 1e-12)),
                         np.log(max(p[3], 1e-12)), np.log(max(p[4], 1e-12))])
    y_min = max(float(y.min()), 0.5)
    y_span = max(float(y.max() - y.min()), 0.1)
    base_init = np.array([y_min * 0.8, y_span, 0.08, y_span * 5, 0.25])
    bp = _fit_nls(X, y, base_pred, base_unpack, base_pack, base_init,
                  n_restarts=10, use_log=False)
    # Stage 2: full model
    def full_unpack(u):
        return np.array([u[0], np.exp(u[1]), np.exp(u[2]), np.exp(u[3]), np.exp(u[4]),
                         np.exp(u[5]), u[6], u[7], u[8], np.exp(u[9]), u[10], u[11]])
    def full_pack(p):
        E, A, al, B, be, K, la, ln_c, ld_c, M, bd, bb = p
        return np.array([E, np.log(max(A, 1e-12)), np.log(max(al, 1e-12)),
                         np.log(max(B, 1e-12)), np.log(max(be, 1e-12)),
                         np.log(max(K, 1e-12)), la, ln_c, ld_c,
                         np.log(max(M, 1e-12)), bd, bb])
    E0, A0, al0, B0, be0 = bp
    full_init = np.array([E0, A0, al0, B0, be0,
                          0.005, float(np.log(np.median(lr))), -0.05, -0.05,
                          0.005, 0.05, float(np.log(np.median(bsz)))])
    return _fit_nls(X, y, _lrbsz_predict_phys, full_unpack, full_pack, full_init,
                    n_restarts=16, use_log=False, f_scale=0.05)


def _lrbsz_fit(X, y):
    y = np.asarray(y, dtype=float)
    poly_model, mse_poly = _lrbsz_fit_poly(X, y)
    phys_params = _lrbsz_fit_phys(X, y)
    pred_phys = _lrbsz_predict_phys(X, phys_params)
    mse_phys = float(np.mean((pred_phys - y) ** 2))
    # Also try a blended prediction
    if mse_poly <= mse_phys:
        return poly_model, mse_poly
    return ("phys", phys_params), mse_phys


def _lrbsz_predict(X, model):
    kind = model[0]
    if kind == "linpoly":
        return _lrbsz_predict_linpoly(X, model[1])
    elif kind == "logpoly":
        return _lrbsz_predict_logpoly(X, model[1])
    return _lrbsz_predict_phys(X, model[1])


# ---- DATACONSTRAINED: generalized effective tokens ----

def _dcon_predict(X, params):
    u = np.clip(np.asarray(X[:, 0], dtype=float), 1.0, None)
    n = np.clip(np.asarray(X[:, 1], dtype=float), 1.0, None)
    d = np.clip(np.asarray(X[:, 2], dtype=float), 1.0, None)
    E, A, al, B, be, p = params
    ratio = np.clip(d / u, 0.0, 200.0)
    d_eff = u * (1.0 - np.exp(-np.power(ratio, p)))
    d_eff = np.maximum(d_eff, 1.0)
    return E + A * np.power(n, -al) + B * np.power(d_eff, -be)


def _dcon_fit(X, y):
    y = np.asarray(y, dtype=float)
    def unpack(u):
        return np.array([np.exp(u[0]), np.exp(u[1]), np.exp(u[2]),
                         np.exp(u[3]), np.exp(u[4]), np.exp(u[5])])
    def pack(p):
        return np.array([np.log(max(p[0], 1e-12)), np.log(max(p[1], 1e-12)),
                         np.log(max(p[2], 1e-12)), np.log(max(p[3], 1e-12)),
                         np.log(max(p[4], 1e-12)), np.log(max(p[5], 1e-12))])
    init = np.array([max(y.min() * 0.9, 0.1),
                     max(y.max() - y.min(), 0.1), 0.35,
                     max(y.max() - y.min(), 0.1), 0.35, 1.0])
    return _fit_nls(X, y, _dcon_predict, unpack, pack, init,
                    n_restarts=16, use_log=True, f_scale=0.05)


